var errorTitle=window.localization.error;$(document).ready(()=>{$(document).on("click",".delete-post",function(event){event.preventDefault();var $this=$(this),dataurl=$this.data("url"),id=$this.data("id");$Confirm({},function(result){result.value&&$.ajax({url:dataurl,type:"Get",dataType:"json",data:{}}).done(function(data){if(data.success)$notification.success("",window.localization.deleted_successfully,2e3,"fa fa-check"),$this.parents('tr[id="tr-'+id+'"]').remove();else{var errors=data.errors;errors.length>0&&(txt=MakeErrorsMsg(errors),$notification.error("",txt,3500,"fa fa-exclamation-circle"))}}).fail(function(jqXHR,Status){$notification.error(errorTitle,jqXHR.statusText,2e3,"fa fa-exclamation-circle")})})})}),$(document).ready(()=>{$("#CreateSection").validate({errorClass:"invalid_field",validClass:"valid_field",ignore:".ignore",submitHandler:function(form){return async_fetch($(form).attr("action"),$(form).serialize(),{"Content-Type":"application/x-www-form-urlencoded"}).then(res=>{if(res.success)if($("#errors").length&&$("#errors").remove(),res.sections&&res.sections.length>0){let options="";$.each(res.sections,(ind,item)=>options+="<option value='"+item.value+"'>"+item.text+"</option>"),$("#SectionId").html(options),document.getElementById("CreateSection").reset(),$("#sectionModal").modal("hide")}else window.location.reload();else{var txt=MakeErrorsMsg(res.errors);$("#errors").show().find(".content").html(txt)}}),!1}})});